const upsertMarketDailyBar = `-- name: UpsertMarketDailyBar :exec
INSERT INTO market_daily_bar (symbol, day_utc, close)
VALUES ($1, $2, $3)
ON CONFLICT (symbol, day_utc) DO UPDATE SET close = EXCLUDED.close
`

